import itertools
import numpy as np
def _conserved(n, s_tot, k_tot, f_tot):
    d = 2 * n + 4
    rows = []
    for x in itertools.product(range(max(s_tot, k_tot, f_tot) + 1), repeat=d):
        s = x[0] + x[1] + sum(x[4:4 + n]) + sum(x[4 + n:])
        if s == s_tot and x[2] + sum(x[4:4 + n]) == k_tot and x[3] + sum(x[4 + n:]) == f_tot:
            rows.append(x)
    return np.array(rows, dtype=np.int64)
def _digest(stack):
    g = np.asarray(stack, dtype=float)
    if g.ndim != 3 or g.shape[1] != g.shape[2]:
        return -1.0
    m = g.shape[1]
    w = np.outer(np.arange(1.0, m + 1.0), np.sqrt(np.arange(1.0, m + 1.0)))
    per = np.array([np.sum(w * b) + 0.5 * np.sum(w * np.abs(b)) for b in g])
    return float(g.shape[0] + 1.0e-3 * m + 1.0e-4 * np.sum(per * np.log(np.arange(2.0, g.shape[0] + 2.0))) / m)
states = _conserved(2, 2, 1, 1)
assert np.allclose(_digest(build_channel_generators(2, states.copy())), target)

