import numpy as np
def _isomerization(total):
    # State index a = number of A molecules; channel 0 is A -> B, channel 1 is B -> A.
    g = np.zeros((2, total + 1, total + 1))
    for a in range(total + 1):
        if a > 0:
            g[0, a, a - 1], g[0, a, a] = a, -a
        if a < total:
            g[1, a, a + 1], g[1, a, a] = total - a, -(total - a)
    return g
def _digest(v):
    v = np.asarray(v, dtype=float)
    if v.ndim != 1:
        return -1.0
    w = np.sqrt(np.arange(1.0, v.size + 1.0))
    return float(v.size + 1.0e-3 * np.sum(w * v) + 1.0e-3 * np.sum(v ** 2 / w))
G = _isomerization(3)
f = np.arange(4.0)
assert np.allclose(_digest(compute_observable_derivatives(G.copy(), np.array([0.7, 0.4]), 3, f.copy(), 1.5, 0, 5)), target)

